import {getAction} from '@madou/catalog';
import {createGame,gameStats} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const guardianPhysicalScenarios=['guardian-setup','guardian-turn','guardian-equal','guardian-higher','guardian-fail','guardian-waive','guardian-ignore','guardian-ignore-decline','guardian-sky','guardian-sky-decline','guardian-destroy','guardian-invalid','guardian-army','guardian-ded-hand','guardian-ded-field','guardian-black','guardian-black-fail'] as const;
export type GuardianPhysicalScenario=typeof guardianPhysicalScenarios[number];
export function isGuardianPhysicalScenario(name:string):name is GuardianPhysicalScenario{return (guardianPhysicalScenarios as readonly string[]).includes(name);}
export function guardianPhysicalMode(name:GuardianPhysicalScenario){const defense=!name.includes('-ded-')&&!name.includes('-grant-')&&!name.endsWith('-army'),ignore=name.includes('-ignore'),sky=name.includes('-sky'),invalid=name.endsWith('-invalid'),destroy=name.endsWith('-destroy'),decline=name.endsWith('-decline'),waive=name.endsWith('-waive'),black=name.includes('-black');return{card:'a2-p22-r3c3',name:'守護者',level:7,hp:0,attributes:['白','空'],defense,army:name.endsWith('-army'),dedicated:name.includes('-ded-'),fail:name.endsWith('-fail')||decline,waive,black,ignore,sky,invalid,destroy,decline,special:waive||invalid||destroy,front:sky?'a2-p20-r3c1':'a2-p22-r1c1',column:ignore||sky||invalid,attackLevel:name.endsWith('-equal')||waive?7:name.endsWith('-higher')||name.endsWith('-fail')?8:6,initial:defense&&!name.endsWith('-turn')||name.endsWith('-field')};}
/** Only initial characters/training/deals are scripted; placement and effects use actual commands. */
export function makeGuardianPhysicalScenario(name:GuardianPhysicalScenario,players:{id:string;name:string}[],options:{dwarf?:boolean;level?:number;warrior?:number;magic?:number;spirit?:number;owner?:string;multi?:boolean;defender?:string}={}){
 const m=guardianPhysicalMode(name),s=createGame(players,entropy(),{startingSeat:0}),[a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[options.owner??(!m.defense||m.special?'リーア姫':'竜皇子アスフェルト'),options.defender??(m.ignore?'不死王ガドューラ':m.sky?'有翼人のティア':m.invalid?'吟遊詩人のレスター':m.destroy?'占星術師のアルセイル':m.black?'黒騎士ガーウィン':m.defense?'魔聖母ディア':'白魔術師シェリム'),'凍気のアイエル','侍大将のシン'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+14-gameStats(s,p.id).spirit;}
 if(options.level!==undefined||m.defense)s.players[b]!.permanent!.warrior_level=20+(options.level??m.attackLevel)-gameStats(s,b).warrior_level;
 if(options.warrior!==undefined)s.players[a]!.permanent!.warrior_level=20+options.warrior-gameStats(s,a).warrior_level;
 if(options.magic!==undefined)s.players[a]!.permanent!.magic_level=20+options.magic-gameStats(s,a).magic_level;
 if(options.spirit!==undefined||m.fail||m.waive)s.players[a]!.permanent!.spirit=s.players[a]!.permanent!.spirit!+(options.spirit??0)-gameStats(s,a).spirit;
 const keep=[takeCard(s,a,m.card),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,a,options.multi?'a2-p24-r2c2':m.front),takeCard(s,a,m.army?'a2-p05-r2c2':options.multi?'a2-p24-r2c3':'a2-p23-r1c1'),takeCard(s,a,'a2-p07-r1c1'),takeCard(s,b,'a2-p24-r1c2'),takeCard(s,b,'a2-p24-r2c1'),takeCard(s,b,m.ignore||m.invalid?'a2-p21-r1c1':m.sky?'a2-p15-r1c3':m.destroy?'a2-p13-r1c2':m.black?'a2-p15-r2c2':'a2-p21-r2c3'),takeCard(s,b,'a2-p07-r1c2'),takeCard(s,b,m.invalid?'a2-p05-r2c2':m.black?'a2-p05-r2c3':'a2-p11-r1c3'),takeCard(s,d,'a2-p02-r2c3')];
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 const cursors:Record<string,number>={};s.events=s.events.flatMap(event=>{if(event.type==='CHARACTER_ASSIGNED')return[{...event,characterId:s.players[event.actorId]!.characterId}];if(event.type!=='CARD_DRAWN')return[event];const index=cursors[event.actorId]??0;cursors[event.actorId]=index+1;const cardInstanceId=s.players[event.actorId]!.hand[index];return cardInstanceId?[{...event,cardInstanceId}]:[];});return s;
}
